create table public.products (id text primary key, slug text not null unique, brand text not null, name text not null, category text not null check(category='phone'), description text not null, image text not null, specs jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_variants (id text primary key, product_id text not null references public.products(id) on delete cascade, storage text not null, color text not null, region text not null, condition text not null check(condition in ('全新','二手','官翻')), performance integer not null check(performance between 0 and 100), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.offers (id text primary key, variant_id text not null references public.product_variants(id) on delete cascade, platform text not null check(platform in ('京东','淘宝','拼多多')), seller text not null, title text not null, price numeric(12,2) not null check(price >= 0), original_price numeric(12,2) check(original_price is null or original_price >= price), rating numeric(2,1) not null check(rating between 0 and 5), sales integer not null check(sales >= 0), shipping text not null, warranty text not null, url text not null, updated_at timestamptz not null, match_confidence numeric(3,2) not null check(match_confidence between 0 and 1));
create index product_variants_product_id_idx on public.product_variants(product_id); create index offers_variant_id_idx on public.offers(variant_id); create index offers_price_idx on public.offers(variant_id,price); create index products_category_idx on public.products(category);
alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.offers enable row level security;
revoke all on public.products,public.product_variants,public.offers from anon,authenticated;
grant select on public.products,public.product_variants,public.offers to anon,authenticated;
create policy "catalog public read" on public.products for select to anon,authenticated using(true); create policy "variants public read" on public.product_variants for select to anon,authenticated using(true); create policy "offers public read" on public.offers for select to anon,authenticated using(true);
